26	
27	using namespace op;
28	
29	#ifdef __cplusplus
30	extern "C" {
31	#endif
32	
33	static const std::initializer_list<DataType> FLOAT_DTYPE_SUPPORT_LIST = {DataType::DT_FLOAT, DataType::DT_FLOAT16};
34	
35	static const std::initializer_list<DataType> INT_DTYPE_SUPPORT_LIST = {DataType::DT_INT32};
36	
37	static bool CheckNotNull(const aclTensor* self, const aclTensor* rois, const aclTensor* batchIndices,
38	                         const aclTensor* out)
39	{
40	    OP_CHECK_NULL(self, return false);
41	    OP_CHECK_NULL(rois, return false);
42	    OP_CHECK_NULL(batchIndices, return false);
43	    OP_CHECK_NULL(out, return false);
44	    return true;
45	}
46	
47	static bool CheckDtypeValid(const aclTensor* self, const aclTensor* rois, const aclTensor* batchIndices,
48	                            const aclTensor* out)
49	{
50	    OP_CHECK_DTYPE_NOT_SUPPORT(self, FLOAT_DTYPE_SUPPORT_LIST, return false);
51	    OP_CHECK_DTYPE_NOT_SUPPORT(batchIndices, INT_DTYPE_SUPPORT_LIST, return false);
52	
53	    OP_CHECK_DTYPE_NOT_MATCH(self, rois->GetDataType(), return false);
54	    OP_CHECK_DTYPE_NOT_MATCH(self, out->GetDataType(), return false);
55	
56	    return true;
57	}
58	
59	static bool CheckFormatValid(const aclTensor* self, const aclTensor* rois, const aclTensor* batchIndices,
60	                             const aclTensor* out)
61	{
62	    if (self->GetStorageFormat() != op::Format::FORMAT_NCHW || rois->GetStorageFormat() != op::Format::FORMAT_ND ||
63	        batchIndices->GetStorageFormat() != op::Format::FORMAT_ND ||
64	        out->GetStorageFormat() != op::Format::FORMAT_NCHW) {
65	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
66	                "Format error. self and out only support NCHW, rois and batchIndices only support ND.");
67	        return false;
68	    }
69	
70	    return true;
71	}
72	
73	static bool CheckShape(const aclTensor* self, const aclTensor* rois, const aclTensor* batchIndices,
74	                       const aclTensor* out, int outputHeight, int outputWidth)
75	{
76	    OP_CHECK_WRONG_DIMENSION(self, 4, return false);
77	    OP_CHECK_WRONG_DIMENSION(rois, 2, return false);
78	    OP_CHECK_WRONG_DIMENSION(batchIndices, 1, return false);
79	    OP_CHECK_WRONG_DIMENSION(out, 4, return false);
80	
81	    auto const& selfShape = self->GetViewShape();
82	    auto const& roisShape = rois->GetViewShape();
83	    auto const& batchIndicesShape = batchIndices->GetViewShape();
84	    auto const& outShape = out->GetViewShape();
85	    if (roisShape.GetDim(0) != batchIndicesShape.GetDim(0)) {
86	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "rois shape dim0 [%ld] and batchIndices shape dim0 [%ld] should be equal",
87	                roisShape.GetDim(0), batchIndicesShape.GetDim(0));
88	        return false;
89	    }
90	    if (roisShape.GetDim(1) != 4) { // 4: rois dim 1
91	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "rois shape dim1 [%ld] should be 4", roisShape.GetDim(1));
92	        return false;
93	    }
94	    if (outShape.GetDim(0) != roisShape.GetDim(0)) {
95	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "out shape dim0 [%ld] and rois shape dim0 [%ld] should be equal",
96	                outShape.GetDim(0), roisShape.GetDim(0));
97	        return false;
98	    }
99	    if (outShape.GetDim(1) != selfShape.GetDim(1)) {
100	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "out shape dim1 [%ld] and self shape dim1 [%ld] should be equal",
101	                outShape.GetDim(1), selfShape.GetDim(1));
102	        return false;
103	    }
104	    if (outShape.GetDim(2) != outputHeight) { // 2: dim2
105	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "out shape dim2 [%ld] and outputHeight [%d] should be equal",
106	                outShape.GetDim(2), outputHeight); // 2: dim2
107	        return false;
108	    }
109	    if (outShape.GetDim(3) != outputWidth) { // 3: dim3
110	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "out shape dim3 [%ld] and outputWidth [%d] should be equal",
111	                outShape.GetDim(3), outputWidth); // 3: dim3
112	        return false;
113	    }
114	
115	    return true;
116	}
117	
118	static bool CheckAttr(const char* mode, int samplingRatio, float spatialScale)
119	{
120	    if (mode == nullptr) {
121	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "mode is null, please check input arguments");
122	        return false;
123	    }
124	    if (strcmp(mode, "avg") != 0 && strcmp(mode, "max") != 0) {
125	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "mode should be [avg] or [max], but get [%s]", mode);
126	        return false;
127	    }
128	    if (samplingRatio < 0) {
129	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "samplingRatio [%d] should be greater than or equal to 0", samplingRatio);
130	        return false;
131	    }
132	    if (spatialScale <= 0) {
133	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "spatialScale [%f] should be greater than 0", spatialScale);
134	        return false;
135	    }
136	    return true;
137	}
138	
139	static aclnnStatus CheckParams(const aclTensor* self, const aclTensor* rois, const aclTensor* batchIndices,
140	                               const aclTensor* out, const char* mode, int outputHeight, int outputWidth,
141	                               int samplingRatio, float spatialScale)
142	{
143	    // 1. 检查参数是否为空指针
144	    CHECK_RET(CheckNotNull(self, rois, batchIndices, out), ACLNN_ERR_PARAM_NULLPTR);
145	
146	    // 2. 检查输入、输出的数据类型是否在API支持的数据类型范围之内，需要根据api定义校验
147	    CHECK_RET(CheckDtypeValid(self, rois, batchIndices, out), ACLNN_ERR_PARAM_INVALID);
148	
149	    // 3. 检查输入、输出的数据格式是否支持
150	    CHECK_RET(CheckFormatValid(self, rois, batchIndices, out), ACLNN_ERR_PARAM_INVALID);
151	
152	    // 4. 检查输入tensor的shape
153	    CHECK_RET(CheckShape(self, rois, batchIndices, out, outputHeight, outputWidth), ACLNN_ERR_PARAM_INVALID);
154	
155	    // 5. 检查属性
156	    CHECK_RET(CheckAttr(mode, samplingRatio, spatialScale), ACLNN_ERR_PARAM_INVALID);
157	
158	    return ACLNN_SUCCESS;
159	}
160	
161	static const aclTensor* GetOutTensorWithValueZero(aclTensor* out, aclOpExecutor* executor)
162	{
163	    aclScalar* scalar = executor->AllocScalar(0);
164	    auto valueTensor = executor->ConvertToTensor(scalar, out->GetDataType());
165	    auto outputDims = op::ToShapeVector(out->GetViewShape());
166	    aclIntArray* dimArray = executor->AllocIntArray(outputDims.data(), outputDims.size());
167	    auto dimTensor = executor->ConvertToTensor(dimArray, op::DataType::DT_INT64);
168	    return l0op::Fill(dimTensor, valueTensor, dimArray, executor);
169	}
170	
171	aclnnStatus aclnnRoiAlignGetWorkspaceSize(const aclTensor* self, const aclTensor* rois, const aclTensor* batchIndices,
172	                                          const char* mode, int outputHeight, int outputWidth, int samplingRatio,
173	                                          float spatialScale, aclTensor* out, uint64_t* workspaceSize,
174	                                          aclOpExecutor** executor)
175	{
176	    L2_DFX_PHASE_1(aclnnRoiAlign,
177	                   DFX_IN(self, rois, batchIndices, mode, outputHeight, outputWidth, samplingRatio, spatialScale),
178	                   DFX_OUT(out));
179	    // 固定写法，创建OpExecutor
180	    auto uniqueExecutor = CREATE_EXECUTOR();
181	    CHECK_RET(uniqueExecutor.get() != nullptr, ACLNN_ERR_INNER_CREATE_EXECUTOR);
182	
183	    // 固定写法，参数检查
184	    auto ret = CheckParams(self, rois, batchIndices, out, mode, outputHeight, outputWidth, samplingRatio, spatialScale);
185	    CHECK_RET(ret == ACLNN_SUCCESS, ret);
186	
187	    // roialign算子的空tensor在kernel中支持
188	    if (self->IsEmpty() || rois->IsEmpty()) {
189	        // 根据实际支持情况补充
190	        auto fillOut = GetOutTensorWithValueZero(out, uniqueExecutor.get());
191	        CHECK_RET(fillOut != nullptr, ACLNN_ERR_INNER_NULLPTR);
192	
193	        auto viewCopyResult = l0op::ViewCopy(fillOut, out, uniqueExecutor.get());
194	        CHECK_RET(viewCopyResult != nullptr, ACLNN_ERR_INNER_NULLPTR);
195	
196	        *workspaceSize = uniqueExecutor->GetWorkspaceSize();
197	        uniqueExecutor.ReleaseTo(executor);
198	        return ACLNN_SUCCESS;
199	    }
200	
201	    // 固定写法，将输入self转换成连续的tensor
202	    auto selfContiguous = l0op::Contiguous(self, uniqueExecutor.get());
203	    CHECK_RET(selfContiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
204	
205	    // 固定写法，将输入rois转换成连续的tensor
206	    auto roisContiguous = l0op::Contiguous(rois, uniqueExecutor.get());
207	    CHECK_RET(roisContiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
208	
209	    // 固定写法，将输入batchIndices转换成连续的tensor
210	    auto batchIndicesContiguous = l0op::Contiguous(batchIndices, uniqueExecutor.get());
211	    CHECK_RET(batchIndicesContiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
212	
213	    // 将self转为私有格式NC1HWC0
214	    auto selfTransData = l0op::TransDataSpecial(selfContiguous, op::Format::FORMAT_NC1HWC0, 0, uniqueExecutor.get());
215	    CHECK_RET(selfTransData != nullptr, ACLNN_ERR_INNER_NULLPTR);
216	
217	    // 将batchIndices补充成2维[num_rois, 1]
218	    int64_t batchIndicesNewShape[2] = {batchIndices->GetViewShape().GetDim(0), 1};        // 2: dim num
219	    auto batchIndicesSize = uniqueExecutor.get()->AllocIntArray(batchIndicesNewShape, 2); // 2: dim num
220	    auto batchIndicesReshape = l0op::Reshape(batchIndicesContiguous, batchIndicesSize, uniqueExecutor.get());
221	    CHECK_RET(batchIndicesReshape != nullptr, ACLNN_ERR_INNER_NULLPTR);
222	
223	    // 将batchIndices转为rois的数据类型
224	    auto batchIndicesCast = l0op::Cast(batchIndicesReshape, rois->GetDataType(), uniqueExecutor.get());
225	    CHECK_RET(batchIndicesCast != nullptr, ACLNN_ERR_INNER_NULLPTR);
226	
227	    // 将batchIndices与rois拼接成新rois，shape为[num_rois, 5]
228	    op::FVector<const aclTensor*> tensorListTemp;
229	    tensorListTemp.emplace_back(batchIndicesCast);
230	    tensorListTemp.emplace_back(roisContiguous);
231	    auto tensorList = uniqueExecutor.get()->AllocTensorList(tensorListTemp.data(), tensorListTemp.size());
232	    auto roisConcat = l0op::ConcatD(tensorList, 1, rois->GetDataType(), uniqueExecutor.get());
233	    CHECK_RET(roisConcat != nullptr, ACLNN_ERR_INNER_NULLPTR);
234	
235	    // 进行计算
236	    auto roiAlignOut = l0op::ROIAlign(selfTransData, roisConcat, batchIndicesContiguous, spatialScale, outputHeight,
237	                                      outputWidth, samplingRatio, mode, uniqueExecutor.get());
238	    CHECK_RET(roiAlignOut != nullptr, ACLNN_ERR_INNER_NULLPTR);
239	
240	    // 将roiAlignOut的私有格式数据转为NCHW
241	    auto outTransData = l0op::TransDataSpecial(roiAlignOut, out->GetOriginalFormat(), 0, uniqueExecutor.get());
242	    CHECK_RET(outTransData != nullptr, ACLNN_ERR_INNER_NULLPTR);
243	
244	    // 固定写法，将计算结果拷贝到输出out上，out可能是非连续的tensor
245	    auto viewCopyResult = l0op::ViewCopy(outTransData, out, uniqueExecutor.get());
246	    CHECK_RET(viewCopyResult != nullptr, ACLNN_ERR_INNER_NULLPTR);
247	
248	    // 固定写法，获取计算过程中需要使用的workspace大小
249	    *workspaceSize = uniqueExecutor->GetWorkspaceSize();
250	    uniqueExecutor.ReleaseTo(executor); // 需要把 uniqueExecutor持有executor转移给executor
251	    return ACLNN_SUCCESS;
252	}
253	
254	aclnnStatus aclnnRoiAlign(void* workspace, uint64_t workspaceSize, aclOpExecutor* executor, const aclrtStream stream)
255	{
256	    L2_DFX_PHASE_2(aclnnRoiAlign);
257	
258	    return CommonOpExecutorRun(workspace, workspaceSize, executor, stream);
259	}
260	
261	#ifdef __cplusplus
262	}
263	#endif

